def primeSubarray(nums, k):
    from collections import deque

    # Sieve of Eratosthenes up to max value.
    max_num = max(max(nums), 2)
    is_prime = [False, False] + [True] * (max_num - 1)
    for i in range(2, int(max_num ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, max_num + 1, i):
                is_prime[j] = False

    n = len(nums)
    maxd = deque()      # indices of primes, values decreasing (front = max)
    mind = deque()      # indices of primes, values increasing (front = min)
    prime_idx = deque() # indices of all primes currently in window
    left = 0
    res = 0

    for right in range(n):
        v = nums[right]
        if is_prime[v]:
            while maxd and nums[maxd[-1]] <= v:
                maxd.pop()
            maxd.append(right)
            while mind and nums[mind[-1]] >= v:
                mind.pop()
            mind.append(right)
            prime_idx.append(right)

        # Shrink while the window has >= 2 primes and their value gap exceeds k.
        while len(prime_idx) >= 2 and nums[maxd[0]] - nums[mind[0]] > k:
            left += 1
            while maxd and maxd[0] < left:
                maxd.popleft()
            while mind and mind[0] < left:
                mind.popleft()
            while prime_idx and prime_idx[0] < left:
                prime_idx.popleft()

        # Every start in [left, right] keeps gap <= k (subset of primes).
        # We need >= 2 primes, so start must be <= index of the 2nd prime from the right.
        if len(prime_idx) >= 2:
            second_last = prime_idx[-2]
            res += second_last - left + 1

    return res
